CREATE TABLE sales_stock_requests (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, sales_hall_id BINARY(16) NOT NULL, warehouse_id BINARY(16) NOT NULL, status VARCHAR(32) NOT NULL, notes VARCHAR(2000), created_by BINARY(16) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_sales_request_org (organization_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE sales_stock_request_items (id BINARY(16) PRIMARY KEY, sales_stock_request_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, requested_quantity DECIMAL(14,2) NOT NULL, approved_quantity DECIMAL(14,2) NOT NULL, received_quantity DECIMAL(14,2) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY (sales_stock_request_id) REFERENCES sales_stock_requests(id));
CREATE TABLE sales_receipts (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, sales_hall_id BINARY(16) NOT NULL, warehouse_output_id BINARY(16) NOT NULL, sales_stock_request_id BINARY(16), status VARCHAR(32) NOT NULL, received_by BINARY(16) NOT NULL, received_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_sales_receipt_output (warehouse_output_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE sales_receipt_items (id BINARY(16) PRIMARY KEY, sales_receipt_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, quantity DECIMAL(14,2) NOT NULL, serial_reference VARCHAR(255), batch_reference VARCHAR(255), location_id BINARY(16), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY (sales_receipt_id) REFERENCES sales_receipts(id));
CREATE TABLE sales_prices (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, sales_hall_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, current_price DECIMAL(14,2) NOT NULL, updated_by BINARY(16) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_sales_price_hall_product (organization_id,sales_hall_id,product_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE sales_price_history (id BINARY(16) PRIMARY KEY, sales_price_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, sales_hall_id BINARY(16) NOT NULL, previous_price DECIMAL(14,2), new_price DECIMAL(14,2) NOT NULL, changed_by BINARY(16) NOT NULL, reason VARCHAR(1000), changed_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY (sales_price_id) REFERENCES sales_prices(id));
CREATE TABLE sales_packages (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, sales_hall_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, weight DECIMAL(14,2) NOT NULL, unit_price DECIMAL(14,2) NOT NULL, total_price DECIMAL(14,2) NOT NULL, status VARCHAR(32) NOT NULL, qr_reference VARCHAR(255), created_by BINARY(16) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE sales_returns (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, sales_hall_id BINARY(16) NOT NULL, destination_warehouse_id BINARY(16) NOT NULL, status VARCHAR(32) NOT NULL, reason VARCHAR(1000), notes VARCHAR(2000), created_by BINARY(16) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE sales_return_items (id BINARY(16) PRIMARY KEY, sales_return_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, requested_quantity DECIMAL(14,2) NOT NULL, received_quantity DECIMAL(14,2) NOT NULL, serial_reference VARCHAR(255), batch_reference VARCHAR(255), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY (sales_return_id) REFERENCES sales_returns(id));